const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const imgs={sea:'https://www.travelsewhere.net/wp-content/uploads/2024/05/DSC_0684-17.jpg',village:'https://cdn.sanity.io/images/nxpteyfv/goguides/d47e6af783f73cb63ef98a6153f1029064348ebf-1600x1066.jpg'};
const places=[{id:'gamcheon',name:'甘川文化村',en:'GAMCHEON CULTURE VILLAGE',area:'沙下區',cat:'文化',img:imgs.village,desc:'沿著彩色山城的巷弄散步，把繽紛屋頂和遠方的海一起收藏。',ko:'감천문화마을'}, {id:'gwangalli',name:'廣安里海水浴場',en:'GWANGALLI BEACH',area:'水營區',cat:'海岸',img:imgs.sea,desc:'留一段不趕路的時間，沿著沙灘散步，欣賞海面上的廣安大橋。',ko:'광안리해수욕장'}, {id:'haeundae',name:'海雲台海水浴場',en:'HAEUNDAE BEACH',area:'海雲台區',cat:'海岸',img:'https://www.unesco.de/assets/bilder_und_videos/Kultur/02_Welterbe/Fotos/Busan_City_Haeundae_Beach_KOGL.jpg',desc:'把步調交給海浪，在沙灘與海岸步道之間，找到舒服的旅行節奏。',ko:'해운대해수욕장'}, {id:'jagalchi',name:'札嘎其市場',en:'JAGALCHI MARKET',area:'中區',cat:'美食',img:null,desc:'走進港都的市場日常，看看海鮮攤位，為自己挑一頓喜歡的午餐。',ko:'자갈치시장'}, {id:'yonggungsa',name:'海東龍宮寺',en:'HAEDONG YONGGUNGSA',area:'機張郡',cat:'文化',img:null,desc:'沿著海岸走向寺院，感受岩岸、浪聲與寺廟相遇的風景。',ko:'해동용궁사'}, {id:'biff',name:'BIFF 廣場',en:'BIFF SQUARE',area:'中區',cat:'美食',img:null,desc:'逛逛南浦洞街區，將街頭小吃與隨興的巷弄散步排在一起。',ko:'BIFF광장'}];
const initial={start:'2027-04-15',currency:"TWD",budget:15000,saved:['gamcheon','gwangalli'],days:[[{id:1,time:'14:00',name:'甘川文化村',note:'彩色山城散步 · 帶上相機',cat:'文化',place:'gamcheon'},{id:2,time:'17:00',name:'札嘎其市場',note:'逛市場，享用海鮮午餐',cat:'美食',place:'jagalchi'},{id:3,time:'18:00',name:'BIFF 廣場',note:'街頭小吃與南浦洞漫步',cat:'美食',place:'biff'}],[{id:4,time:'10:00',name:'海雲台海水浴場',note:'海邊散步，找一間咖啡館',cat:'海岸',place:'haeundae'},{id:5,time:'17:00',name:'廣安里海水浴場',note:'把傍晚留給海風',cat:'海岸',place:'gwangalli'}],[{id:6,time:'11:00',name:'海東龍宮寺',note:'沿著海岸，慢慢探索',cat:'文化',place:'yonggungsa'}],[]],expenses:[{id:1,name:'海邊咖啡',amount:162.5,cat:'餐飲',date:'2027-04-15'},{id:2,name:'午餐',amount:375,cat:'餐飲',date:'2027-04-15'},{id:3,name:'交通儲值',amount:500,cat:'交通',date:'2027-04-15'}]};
let state;try{state=JSON.parse(localStorage.getItem('busan-days-v1'))||structuredClone(initial)}catch{state=structuredClone(initial)}let day=0,view='home',filter='全部';const titles=['彩色山城與港都日常','向海出發，追一場日落','海岸寺院與自由時光','留白，給旅途的小驚喜'];const money=n=>new Intl.NumberFormat('zh-TW').format(n);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const dateFor=i=>{let d=new Date(state.start+'T12:00:00');d.setDate(d.getDate()+i);return d};const shortDate=i=>dateFor(i).toLocaleDateString('zh-TW',{month:'2-digit',day:'2-digit'});const isoDate=()=>new Date().toLocaleDateString('en-CA');let toastTimer;
function migrateTwdLedger(ledger){if(ledger.currency==='TWD')return false;ledger.krwPerTwd=40;ledger.originalBudgetKRW=ledger.budget;ledger.budget=Math.round(ledger.budget/40*100)/100;ledger.expenses=ledger.expenses.map(e=>({...e,originalKRW:e.amount,amount:Math.round(e.amount/40*100)/100}));ledger.currency='TWD';return true}
if(migrateTwdLedger(state)){try{localStorage.setItem('busan-days-v1',JSON.stringify(state))}catch{}}
function persist(){try{localStorage.setItem('busan-days-v1',JSON.stringify(state))}catch{toast('瀏覽器無法儲存，請勿關閉此頁面')}render()}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2500)}
function show(v){view=v;$$('[id$="-view"]').forEach(e=>e.hidden=e.id!==v+'-view');$$('nav button').forEach(e=>e.classList.toggle('active',e.dataset.view===v));$('#view-label').textContent={home:'旅行總覽',plan:'我的行程',route:'路線食宿',explore:'探索釜山',saved:'口袋清單',budget:'旅費記帳'}[v];render();window.scrollTo({top:0,behavior:'smooth'})}
function modal(html){$('#modal-body').innerHTML=html;$('#modal').showModal()}function close(){$('#modal').close()}
function icon(cat){return {文化:'⚑',海岸:'≈',美食:'♨',自由:'✦'}[cat]||'✦'}
function timeline(full=false){return state.days[day].map((s,i)=>`<div class="timeline-item"><span class="time">${esc(s.time)}</span><div class="stop"><span class="stop-icon">${icon(s.cat)}</span><div class="stop-info"><h4>${esc(s.name)}</h4><p>${esc(s.note||'留一點時間，慢慢探索')}</p></div><span class="stop-tag">${esc(s.cat)}</span>${full?`<button class="stop-action" data-edit="${s.id}" aria-label="編輯${esc(s.name)}">✎</button><button class="stop-action" data-delete="${s.id}" aria-label="移除${esc(s.name)}">×</button>`:`<button class="stop-action" data-edit="${s.id}" aria-label="編輯${esc(s.name)}">↗</button>`}</div></div>`).join('')||'<div class="empty">這一天還有無限可能。<br><br>加入一個你想去的地方吧。</div>'}
function card(p){let saved=state.saved.includes(p.id);return `<article class="place-card"><div class="card-image" data-detail="${p.id}" tabindex="0" role="button" aria-label="查看${p.name}">${p.img?`<img src="${p.img}" alt="${p.name}" loading="lazy">`:`<div style="height:100%;display:grid;place-items:center;background:${p.cat==='美食'?'#e5d0b0':'#b5c6bb'};font-size:70px;color:#fff9">${icon(p.cat)}</div>`}<span class="image-category">${p.cat==='美食'?'在地滋味':p.cat==='海岸'?'海岸風景':'文化散步'}</span></div><button class="favorite ${saved?'on':''}" data-save="${p.id}" aria-label="${saved?'取消收藏':'收藏'}${p.name}" aria-pressed="${saved}">${saved?'♥':'♡'}</button><div class="place-body"><small>${p.en}</small><h3>${p.name}</h3><p>${p.desc}</p><div class="place-bottom"><span>◎ ${p.area}</span><button data-add-place="${p.id}">＋ 加入行程</button></div></div></article>`}
function render(){let total=Math.round(state.expenses.reduce((a,b)=>a+b.amount,0)*100)/100;$('#saved-count').textContent=state.saved.length;$('#trip-dates').textContent=`${dateFor(0).getFullYear()}. ${shortDate(0)} — ${shortDate(3)}`;$('#trip-total').textContent=state.days.flat().length;let tabs=state.days.map((_,i)=>`<button class="${day===i?'active':''}" data-day="${i}">DAY ${i+1}<small>${shortDate(i)} · ${dateFor(i).toLocaleDateString('zh-TW',{weekday:'short'})}</small></button>`).join('');$('#day-tabs').innerHTML=tabs;$('#plan-tabs').innerHTML=tabs;$('#day-title').textContent=titles[day];$('#day-subtitle').textContent=`${state.days[day].length} 個停留 · 自由安排`;$('#home-timeline').innerHTML=timeline();$('#plan-list').innerHTML=timeline(true);$('#home-spent').innerHTML=`<span>NT$</span>${money(total)}`;$('#budget-progress').style.width=Math.min(100,total/state.budget*100)+'%';$('#budget-caption').textContent=`總預算 NT$ ${money(state.budget)}`;$('#home-cards').innerHTML=places.slice(0,3).map(card).join('');let query=$('#search').value.trim().toLowerCase();let filtered=places.filter(p=>(filter==='全部'||p.cat===filter)&&`${p.name} ${p.en} ${p.area} ${p.cat}`.toLowerCase().includes(query));$('#explore-cards').innerHTML=filtered.map(card).join('')||'<div class="empty">沒有找到符合的景點，試試其他關鍵字。</div>';$('#saved-cards').innerHTML=places.filter(p=>state.saved.includes(p.id)).map(card).join('')||'<div class="empty">口袋清單還是空的。<br><br><button class="text" data-go="explore">去探索喜歡的地方 ↗</button></div>';$('#budget-total').textContent='NT$ '+money(state.budget);$('#budget-spent').textContent='NT$ '+money(total);$('#budget-left').textContent='NT$ '+money(state.budget-total);$('#expense-list').innerHTML=state.expenses.map(e=>`<div class="expense"><span class="stop-icon">${e.cat==='交通'?'▱':'NT$'}</span><div>${esc(e.name)}<small>${esc(e.date)} · ${esc(e.cat)}${e.originalKRW!==undefined?' · 原額 ₩'+money(e.originalKRW):''}</small></div><b>NT$ ${money(e.amount)}</b><button data-expense-delete="${e.id}" aria-label="刪除${esc(e.name)}">刪除</button></div>`).join('')||'<div class="empty">還沒有支出，記下旅行的第一筆吧。</div>'}
function stopForm(placeId,editId){let s=editId?state.days[day].find(x=>x.id===editId):null,p=places.find(x=>x.id===placeId);modal(`<h2>${s?'編輯停留':'新增一段美好停留'}</h2><form id="stop-form"><label>安排在<select name="day">${state.days.map((_,i)=>`<option value="${i}" ${i===day?'selected':''}>Day ${i+1} · ${shortDate(i)}</option>`).join('')}</select></label><label>景點名稱<input name="name" required maxlength="60" value="${esc(s?.name||p?.name||'')}" placeholder="想去哪裡走走？"></label><label>時間<input name="time" type="time" required value="${s?.time||'10:00'}"></label><label>分類<select name="cat">${['文化','海岸','美食','自由'].map(c=>`<option ${c===(s?.cat||p?.cat)?'selected':''}>${c}</option>`).join('')}</select></label><label>給自己的小筆記<input name="note" maxlength="100" value="${esc(s?.note||'')}" placeholder="喝一杯咖啡，或等一場日落"></label><button class="primary">${s?'儲存修改':'加入行程'}</button></form>`);$('#stop-form').onsubmit=e=>{e.preventDefault();let d=new FormData(e.target),target=+d.get('day');if(s)state.days[day]=state.days[day].filter(x=>x.id!==s.id);state.days[target].push({id:s?.id||Date.now(),name:d.get('name').trim()||'自由散步',time:d.get('time'),cat:d.get('cat'),note:d.get('note').trim(),place:s?.place||placeId});state.days[target].sort((a,b)=>a.time.localeCompare(b.time));day=target;persist();close();toast('已儲存到 Day '+(day+1))}}
function detail(id){let p=places.find(x=>x.id===id);modal(`${p.img?`<img class="detail-img" src="${p.img}" alt="${p.name}">`:''}<p>${p.en}</p><h2>${p.name}</h2><p>${p.desc}</p><p>◎ ${p.area} · ${p.cat}<br>韓文名稱：${p.ko}</p><div class="detail-links"><a href="https://map.naver.com/p/search/${encodeURIComponent(p.ko+' 부산')}" target="_blank" rel="noopener">在 NAVER Map 開啟 ↗</a><a href="https://www.visitbusan.net/" target="_blank" rel="noopener">官方旅遊資訊 ↗</a></div><button class="primary" id="detail-add">＋ 加入我的行程</button>`);$('#detail-add').onclick=()=>{close();stopForm(id)}}
function tripSettings(){modal(`<h2>旅行，從這一天開始</h2><p>目前為四日旅程，可自由編輯每天的景點。</p><form id="trip-form"><label>出發日期<input type="date" name="start" value="${state.start}" required min="2020-01-01" max="2100-12-27"></label><button class="primary">儲存旅行日期</button></form>`);$('#trip-form').onsubmit=e=>{e.preventDefault();state.start=new FormData(e.target).get('start');persist();close();toast('旅行日期已更新')}}
document.addEventListener('click',e=>{let b=e.target.closest('button,[data-detail]');if(!b)return;let d=b.dataset;if(d.view)show(d.view);if(d.go)show(d.go);if(d.day!==undefined){day=+d.day;render()}if(d.save){state.saved=state.saved.includes(d.save)?state.saved.filter(x=>x!==d.save):[...state.saved,d.save];persist();toast(state.saved.includes(d.save)?'已放進口袋清單':'已取消收藏')}if(d.detail)detail(d.detail);if(d.addPlace)stopForm(d.addPlace);if(d.edit)stopForm(null,+d.edit);if(d.delete){let item=state.days[day].find(x=>x.id===+d.delete);modal(`<h2>移除此停留？</h2><p>${esc(item.name)}將從 Day ${day+1} 移除。</p><button class="primary" id="confirm-delete">確認移除</button>`);$('#confirm-delete').onclick=()=>{state.days[day]=state.days[day].filter(x=>x.id!==item.id);persist();close();toast('已移除停留')}}if(d.expenseDelete){let item=state.expenses.find(x=>x.id===+d.expenseDelete);modal(`<h2>刪除這筆支出？</h2><p>${esc(item.name)} · NT$ ${money(item.amount)}</p><button class="primary" id="confirm-delete">確認刪除</button>`);$('#confirm-delete').onclick=()=>{state.expenses=state.expenses.filter(x=>x.id!==item.id);persist();close();toast('已刪除支出')}}if(d.filter){filter=d.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('selected',x.dataset.filter===filter));render()}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-detail]')){e.preventDefault();detail(e.target.dataset.detail)}});$('.brand').onclick=e=>{e.preventDefault();show('home')};$('.close').onclick=close;$('#modal').onclick=e=>{if(e.target===$('#modal')){let r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}};$('#edit-trip').onclick=tripSettings;$('#trip-settings').onclick=tripSettings;$('#add-home').onclick=()=>stopForm();$('#add-plan').onclick=()=>stopForm();$('#sea-detail').onclick=()=>detail('gwangalli');$('#search').oninput=render;
$('#edit-budget').onclick=()=>{modal(`<h2>設定旅費預算</h2><form id="budget-form"><label>總預算（新台幣 TWD）<input name="budget" type="number" min="1" max="999999999" step="0.01" required value="${state.budget}"></label><button class="primary">儲存預算</button></form>`);$('#budget-form').onsubmit=e=>{e.preventDefault();state.budget=+new FormData(e.target).get('budget');delete state.originalBudgetKRW;persist();close();toast('預算已更新')}};
$('#add-expense').onclick=()=>{modal(`<h2>記下旅行的一筆</h2><form id="expense-form"><label>花在哪裡？<input name="name" required maxlength="60" placeholder="例如：海邊咖啡"></label><label>金額（新台幣 TWD）<input name="amount" type="number" min="0.01" max="999999999" step="0.01" required placeholder="例如：160"></label><label>分類<select name="cat"><option>餐飲</option><option>交通</option><option>住宿</option><option>購物</option><option>門票</option><option>其他</option></select></label><label>日期<input name="date" type="date" required value="${isoDate()}"></label><button class="primary">儲存這筆支出</button></form>`);$('#expense-form').onsubmit=e=>{e.preventDefault();let d=new FormData(e.target);state.expenses.push({id:Date.now(),name:d.get('name').trim()||'旅行支出',amount:+d.get('amount'),cat:d.get('cat'),date:d.get('date')});persist();close();toast('已記錄這筆支出')}};render();
